from rcb_kinder import Session
import numpy as np
s=Session();s.reset();site=s.model.site('robot_pinch_site').id
q_down=np.array([0,2.2,3.14,-2.0,0,.8,1.57]);q_up=q_down.copy();q_up[1]=1.15

def info(tag):
 c=np.array([s.data.body(f'cube_{i}').xpos[:2].copy() for i in range(10)])
 print(tag,'t',s.t,'base',np.round(s.data.qpos[87:90],2),'site',np.round(s.data.site(site).xpos,3),'goal',sum(.125<=x<=.875 and 1<=y<=1.375 for x,y in c),'cubes',np.round(c,3).tolist(),flush=True)
def act(q=None,tar=None):
 a=np.zeros(11);a[10]=1
 if q is not None:a[3:10]=np.clip(q-s.data.qpos[90:97],-.1,.1)
 if tar is not None:
  e=np.array(tar)-s.data.qpos[87:90];e[2]=(e[2]+np.pi)%(2*np.pi)-np.pi
  a[:3]=np.clip(e,-.08,.08)
 s.step(a)
def arm(q,n=30):
 for _ in range(n): act(q=q)
def go(t,n=80,q=None):
 for _ in range(n):
  e=np.array(t)-s.data.qpos[87:90];e[2]=(e[2]+np.pi)%(2*np.pi)-np.pi
  if np.linalg.norm(e)<.02:break
  act(q=q,tar=t)
 info('go '+str(t))
with s.recording() as rec:
 for t in [[2,1.8,-1.58],[2,-.3,-1.58],[2,-.3,1.57],[1.5,-.3,1.57]]:go(t,110)
 arm(q_down,70); info('lower')
 for x in [1.5,1.4,1.3,1.6,1.7,1.45,1.55]:
  # initially x1.5; after each north stroke raise before returning to southern start
  if abs(s.data.qpos[87]-x)>.03 or s.data.qpos[88]>-.2:
   arm(q_up,16);go([x,-.3,1.57],50,q_up);arm(q_down,30)
  go([x,1.12,1.57],50,q_down)
print('replay',s.replay(rec.actions));s.save_trajectory(rec.actions,'/app/output/trial_lanes.npz')
